enum MyResult {
  Success(value: Int),
  Failure(reason: Str),
}

fn divide_safely(a: Int, b: Int) -> MyResult {
  if b == 0 {
    return MyResult.Failure("Cannot divide by zero");
  }
  return MyResult.Success(a / b);
}

fn parse_age(input: Str) -> MyResult {
  if string.str_len(input) == 0 {
    return MyResult.Failure("Empty age");
  }
  return MyResult.Success(0);
}

fn main() -> Int {
  let r1 = divide_safely(15, 3);
  let r2 = divide_safely(15, 0);
  match r1 {
    Success(v) => io.println(v),
    Failure(msg) => io.println(msg),
  }
  match r2 {
    Success(v) => io.println(v),
    Failure(msg) => io.println(msg),
  }
  return 0;
}
